CREATE OR REPLACE FUNCTION public.checklist_escopo_loja(p_cust text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_super_admin() OR EXISTS(SELECT 1 FROM usuario_permissao_estado WHERE user_id=auth.uid() AND legado AND revisado_em IS NULL) OR p_cust=ANY(public.get_allowed_cust_ids()); $$;
REVOKE ALL ON FUNCTION public.checklist_escopo_loja(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.checklist_escopo_loja(text) TO authenticated,service_role;
CREATE POLICY checklist_seller_scope ON public.sellers AS RESTRICTIVE FOR SELECT TO authenticated USING(public.checklist_escopo_loja(cust_id));
CREATE POLICY master_all_sellers ON public.sellers FOR SELECT TO authenticated USING(public.is_super_admin());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['sellers_kpi','sellers_kpi_daily','live_listings','seller_eligibility','seller_listings_quality','meli_campaigns','metas_loja','seller_grants'] LOOP EXECUTE format('CREATE POLICY checklist_seller_scope ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.sellers s WHERE s.id=seller_id AND public.checklist_escopo_loja(s.cust_id)))',t); EXECUTE format('CREATE POLICY master_read_scope ON public.%I FOR SELECT TO authenticated USING(public.is_super_admin())',t); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['cpp_mensal','cdp_mensal','gm_elegibilidade','gm_live_listings','raw_cpp_mensal','raw_cdp_mensal'] LOOP EXECUTE format('CREATE POLICY checklist_cust_scope ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING (public.checklist_escopo_loja(cus_cust_id_sel::text))',t); EXECUTE format('CREATE POLICY master_read_scope ON public.%I FOR SELECT TO authenticated USING(public.is_super_admin())',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.ml_contas_gerenciaveis() RETURNS TABLE(id uuid,ml_user_id bigint,nickname text,site_id text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.ml_user_id,a.nickname,a.site_id FROM ml_accounts a WHERE a.status='active' AND public.ml_pode_gerir_conta(a.id) AND public.guard_permissao_tabela('ml_accounts',false) ORDER BY a.nickname NULLS LAST,a.ml_user_id; $$;
CREATE OR REPLACE FUNCTION public.ml_contas_status() RETURNS TABLE(account_id uuid,ml_user_id bigint,nickname text,site_id text,status text,token_expira_em timestamptz,tem_token boolean,jobs_total integer,jobs_concluidos integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.ml_user_id,a.nickname,a.site_id,a.status,t.expires_at,t.id IS NOT NULL,coalesce(j.total,0)::int,coalesce(j.ok,0)::int FROM ml_accounts a LEFT JOIN LATERAL(SELECT id,expires_at FROM ml_tokens WHERE account_id=a.id AND is_current ORDER BY created_at DESC LIMIT 1)t ON true LEFT JOIN LATERAL(SELECT count(*) total,count(*) FILTER(WHERE status='done') ok FROM sync_jobs WHERE account_id=a.id AND trilha='backfill')j ON true WHERE public.tem_permissao('integracoes.visualizar') AND (public.is_super_admin() OR (public.checklist_escopo_loja(a.ml_user_id::text) AND (a.ml_user_id::text=ANY(public.get_allowed_cust_ids()) OR EXISTS(SELECT 1 FROM usuario_permissao_estado WHERE user_id=auth.uid() AND legado AND revisado_em IS NULL)))) ORDER BY a.created_at DESC; $$;
ALTER FUNCTION public.get_data_coverage() SECURITY INVOKER;
DO $$ DECLARE f record; d text; BEGIN FOR f IN SELECT p.oid,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('qualidade_feeds_por_mes','qualidade_divergencias','qualidade_nulos_criticos','qualidade_ultimo_import') LOOP d:=pg_get_functiondef(f.oid); d:=replace(d,'WITH allowed AS (SELECT public.is_admin() OR public.has_role(auth.uid(),''gerente'') AS ok)','WITH allowed AS (SELECT public.tem_permissao(''dados.visualizar'') AND (public.is_admin() OR public.has_role(auth.uid(),''gerente'')) AS ok)'); EXECUTE d; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.ml_minhas_contas_status() RETURNS TABLE(account_id uuid,ml_user_id bigint,nickname text,site_id text,status text,token_expira_em timestamptz,tem_token boolean,jobs_total integer,jobs_concluidos integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.ml_user_id,a.nickname,a.site_id,a.status,t.expires_at,t.id IS NOT NULL,coalesce(j.total,0)::int,coalesce(j.ok,0)::int FROM ml_accounts a LEFT JOIN LATERAL(SELECT id,expires_at FROM ml_tokens WHERE account_id=a.id AND is_current ORDER BY created_at DESC LIMIT 1)t ON true LEFT JOIN LATERAL(SELECT count(*) total,count(*) FILTER(WHERE status='done') ok FROM sync_jobs WHERE account_id=a.id AND trilha='backfill')j ON true WHERE public.tem_permissao('integracoes.visualizar') AND a.conectado_por=auth.uid() ORDER BY a.created_at DESC; $$;